mapper.select:
SELECT * FROM ( -- 数据权限类型表 SELECT id, 0 AS pid, name AS right_name, code AS right_slug, 1 AS node_type, description, sort FROM sys_data_permission_type WHERE project_no = #{projectNo} AND subject_id = #{subjectId}
AND name LIKE CONCAT('%', #{rightName}, '%')
UNION ALL
-- 交互权限表 SELECT id, 0 AS pid, name AS right_name, code AS right_slug, 2 AS node_type, NULL AS description, sort FROM sys_interaction_permission WHERE project_no = #{projectNo} AND subject_id = #{subjectId}
AND name LIKE CONCAT('%', #{rightName}, '%')
UNION ALL
-- 特殊权限表 SELECT id, 0 AS pid, name AS right_name, code AS right_slug, 3 AS node_type, description, sort FROM sys_special_permission WHERE project_no = #{projectNo} AND subject_id = #{subjectId}
AND name LIKE CONCAT('%', #{rightName}, '%')
) AS combined_rights ORDER BY node_type ASC, sort ASC, id ASC
